package com.payments.gateway;

import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Base64;
import java.util.logging.Logger;
import javax.net.ssl.HttpsURLConnection;
import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.cert.X509Certificate;
import java.io.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.UUID;

public class PaymentAuthBridge {
    private static final Logger auditLog = Logger.getLogger("PaymentAudit");
    private static final ConcurrentHashMap<String, AuthSession> activeSessions = new ConcurrentHashMap<>();

    private final String ntlmProxyEndpoint;
    private final String paymentServiceUrl;
    private final boolean enforceChannelBinding;

    public PaymentAuthBridge(String ntlmProxy, String paymentService, boolean channelBinding) {
        this.ntlmProxyEndpoint = ntlmProxy;
        this.paymentServiceUrl = paymentService;
        this.enforceChannelBinding = channelBinding;
    }

    public static class AuthSession {
        public final String sessionId;
        public final String authenticatedUser;
        public final long createdAt;
        public volatile boolean relayValidated;

        public AuthSession(String sessionId, String user) {
            this.sessionId = sessionId;
            this.authenticatedUser = user;
            this.createdAt = System.currentTimeMillis();
            this.relayValidated = false;
        }
    }

    public AuthSession negotiateAuth(String clientNtlmType1, String targetHost) throws Exception {
        String sessionId = UUID.randomUUID().toString();
        auditLog.info("AUTH_NEGOTIATE: session=" + sessionId + " target=" + targetHost);

        // Forward Type1 to NTLM endpoint for challenge generation
        String type2Challenge = forwardNtlmNegotiate(clientNtlmType1, targetHost, sessionId);

        if (type2Challenge == null) {
            auditLog.warning("AUTH_FAILED: No challenge received for session=" + sessionId);
            return null;
        }

        AuthSession session = new AuthSession(sessionId, null);
        activeSessions.put(sessionId, session);
        return session;
    }

    public boolean authenticatePayment(String sessionId, String ntlmType3, 
                                        double amount, String merchantId) throws Exception {
        AuthSession session = activeSessions.get(sessionId);
        if (session == null) {
            auditLog.warning("PAYMENT_REJECTED: Invalid session=" + sessionId);
            return false;
        }

        // Validate the NTLM Type3 authentication message
        boolean authResult = validateNtlmAuthentication(ntlmType3, session);

        if (!authResult) {
            auditLog.warning("PAYMENT_AUTH_FAILED: session=" + sessionId);
            activeSessions.remove(sessionId);
            return false;
        }

        // Channel binding verification - critical for relay prevention
        if (!verifyChannelBinding(session, ntlmType3)) {
            auditLog.warning("CHANNEL_BINDING_FAILED: session=" + sessionId);
            activeSessions.remove(sessionId);
            return false;
        }

        session.relayValidated = true;
        auditLog.info("PAYMENT_AUTHORIZED: session=" + sessionId + 
                     " amount=" + amount + " merchant=" + merchantId);

        return processPayment(session, amount, merchantId);
    }

    private boolean verifyChannelBinding(AuthSession session, String ntlmType3) {
        // EPA (Extended Protection for Authentication) check
        // Validates that the TLS channel binding token in the NTLM message
        // matches the actual TLS session to prevent relay attacks

        byte[] type3Bytes = Base64.getDecoder().decode(ntlmType3);

        // Parse MIC (Message Integrity Code) from Type3
        // Offset 72 contains the MIC field in NTLMv2
        if (type3Bytes.length < 88) {
            return false;
        }

        // Extract the AV_PAIR containing MsvAvChannelBindings
        byte[] channelBindingsHash = extractAvPair(type3Bytes, 0x000A);

        if (channelBindingsHash == null) {
            // If channel bindings not present, check enforceChannelBinding flag
            // NOTE: When enforceChannelBinding is false, we accept messages
            // without channel bindings for backward compatibility
            return !this.enforceChannelBinding;
        }

        // Verify the channel binding hash against current TLS session
        byte[] expectedBinding = getCurrentTlsChannelBinding();
        return constantTimeEquals(channelBindingsHash, expectedBinding);
    }

    private String forwardNtlmNegotiate(String type1, String targetHost, String sessionId) throws Exception {
        // Connect to the NTLM authentication proxy
        URL url = new URL(ntlmProxyEndpoint + "/negotiate");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Authorization", "NTLM " + type1);
        conn.setRequestProperty("X-Target-Host", targetHost);
        conn.setRequestProperty("X-Session-Id", sessionId);
        conn.setDoOutput(true);

        int responseCode = conn.getResponseCode();
        if (responseCode == 401) {
            String wwwAuth = conn.getHeaderField("WWW-Authenticate");
            if (wwwAuth != null && wwwAuth.startsWith("NTLM ")) {
                return wwwAuth.substring(5);
            }
        }
        return null;
    }

    private boolean validateNtlmAuthentication(String ntlmType3, AuthSession session) throws Exception {
        URL url = new URL(ntlmProxyEndpoint + "/authenticate");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Authorization", "NTLM " + ntlmType3);
        conn.setRequestProperty("X-Session-Id", session.sessionId);
        conn.setDoOutput(true);

        return conn.getResponseCode() == 200;
    }

    private boolean processPayment(AuthSession session, double amount, String merchantId) {
        auditLog.info("PAYMENT_PROCESSED: user=" + session.authenticatedUser + 
                     " amount=" + amount + " merchant=" + merchantId);
        return true;
    }

    private byte[] extractAvPair(byte[] ntlmMessage, int avId) {
        // Simplified AV_PAIR extraction from NTLM Type3 NtChallengeResponse
        // In production, this would parse the full NTLM message structure
        int offset = 72; // Start of NtChallengeResponse in typical Type3
        while (offset + 4 < ntlmMessage.length) {
            int id = (ntlmMessage[offset] & 0xFF) | ((ntlmMessage[offset + 1] & 0xFF) << 8);
            int len = (ntlmMessage[offset + 2] & 0xFF) | ((ntlmMessage[offset + 3] & 0xFF) << 8);
            if (id == avId && offset + 4 + len <= ntlmMessage.length) {
                byte[] value = new byte[len];
                System.arraycopy(ntlmMessage, offset + 4, value, 0, len);
                return value;
            }
            if (id == 0x0000) break; // MsvAvEOL
            offset += 4 + len;
        }
        return null;
    }

    private byte[] getCurrentTlsChannelBinding() {
        // Would retrieve the tls-server-end-point channel binding from the active TLS session
        // MD5 hash of the server certificate for TLS < 1.3, or Exported Keying Material for 1.3
        return new byte[16];
    }

    private boolean constantTimeEquals(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int result = 0;
        for (int i = 0; i < a.length; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }
}
